#include <bits/stdc++.h>
using namespace std;

const int MOD_A=998244353;
const int MOD_B=1000000007;
long long input_number;
int digits[15], base_vals[15], final_answer;

long long extract_number(int *arr, int len){
    long long res=0;
    for (int i=1; i<=len; i++)
        res=res*10+arr[i];
    return res;
}

long long get_rank(int *arr, int len){
    long long total=0;
    for (int d=1; d<=*digits; d++){
        for (int i=1; i<=min(len,d); i++){
            for (int j=(i==1?1:0); j<arr[i]; j++){
                long long leftPart=0, rightPart=0;
                for (int p=1; p<i; p++)
                    leftPart=rightPart=leftPart*10+arr[p];
                leftPart=rightPart=leftPart*10+j;
                for (int p=i+1; p<=d; p++)
                    leftPart=leftPart*10, rightPart=rightPart*10+9;
                rightPart=min(rightPart, input_number);
                if (leftPart<=rightPart)
                    total+=rightPart-leftPart+1;
            }
        }
        if (d<=len) ++total;
    }
    return total;
}

int computeF(int *arr, int len){
    return ((-extract_number(arr,len)+get_rank(arr,len))%MOD_A+MOD_A)%MOD_A;
}

int diff_vals[15];
int q1_list[1000010], q2_list[1000010];
long long q2_sum[1000010];

void dfs_range(int start, int end, int *q, int v){
    if (start==end){
        for (int i=0; i<=9; i++)
            q[++*q]=(v+1LL*i*diff_vals[start])%MOD_A;
        return;
    }
    for (int i=0; i<=9; i++)
        dfs_range(start+1, end, q, (v+1LL*i*diff_vals[start])%MOD_A);
}

void do_update(int len, int idx, int val){
    int backup[15];
    memcpy(backup, digits, sizeof(digits));
    digits[idx]=val;
    for (int p=idx+1; p<=len; p++) digits[p]=0;
    int baseVal=computeF(digits,len);
    for (int p=idx+1; p<=len; p++){
        digits[p]=1;
        diff_vals[p]=(computeF(digits,len)+MOD_A-baseVal)%MOD_A;
        digits[p]=0;
    }
    if (len-idx==0){
        final_answer=(final_answer+baseVal)%MOD_B;
        return;
    }
    if (len-idx==1){
        for (int p=0; p<=9; p++)
            final_answer=(final_answer+(baseVal+1LL*p*diff_vals[len])%MOD_A)%MOD_B;
        return;
    }
    int mid=(len+idx)/2;
    *q1_list=0; *q2_list=0;
    dfs_range(idx+1, mid, q1_list, baseVal);
    dfs_range(mid+1, len, q2_list, 0);
    std::sort(q2_list+1, q2_list+*q2_list+1);
    long long sumQ2=0;
    for (int i=1; i<=*q2_list; i++)
        sumQ2=(sumQ2+q2_list[i])%MOD_B;
    for (int i=1; i<=*q1_list; i++){
        int p=lower_bound(q2_list+1, q2_list+*q2_list+1, MOD_A - q1_list[i]) - q2_list;
        final_answer=(final_answer+sumQ2+1LL*(*q2_list)*q1_list[i])%MOD_B;
        final_answer=(final_answer+1LL*((*q2_list)-p+1)*(MOD_B-MOD_A))%MOD_B;
    }
}

int main(){
    scanf("%lld", &input_number);
    long long m=input_number;
    for (*digits=0; m; m/=10) digits[++*digits]=m%10;
    std::reverse(digits+1, digits+*digits+1);
    for (int d=1; d<=*digits; d++){
        for (int i=1; i<=d; i++){
            int l=(i==1?1:0);
            int r=(d==*digits?digits[i]-1:9);
            for (int j=l; j<=r; j++)
                if (j!=digits[i]) do_update(d, i, j);
        }
        final_answer=(final_answer+computeF(digits, d))%MOD_B;
    }
    printf("%d\n", final_answer);
}
